const resp = await fetch(

  'https://logs.example.com/searchsse?query=logtype=%22access%22&fromDateTime=22/06/2026%2000:00:00.000&toDateTime=22/06/2026%2023:59:59.999&timezone=Asia/Kolkata&order=desc&range=1-100&appid=12345678&service=tabbridge',

  {

    method: 'GET',

    credentials: 'include',

    headers: {

      accept: 'application/json, text/plain, */*',

      'x-requested-with': 'UI',

    },

  }

);



if (!resp.ok) {

  throw new Error('HTTP ' + resp.status + ' ' + resp.statusText);

}



// searchsse may return SSE text rather than JSON

const contentType = resp.headers.get('content-type') || '';



if (contentType.includes('application/json')) {

  return await resp.json();

}



return await resp.text();
